-- ============================================================================
-- 1. TABLE: gold.dim_date
-- TRANSFORMATIONS: Generated by a SQL script (NOT loaded from source data): one row per calendar
--                  day, 2016-01-01 to 2019-12-31.
-- ==========================================================================
USE [olist_dwh];
GO

IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'dim_date')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[dim_date]
    (
        [date_key]         INT IDENTITY(1,1) NOT NULL,  -- surrogate key (-1 = Unknown row)
        [full_date]        DATE NOT NULL,               -- business key: the calendar date
        [calendar_year]    SMALLINT NOT NULL,           -- e.g. 2017
        [calendar_quarter] TINYINT NOT NULL,            -- 1 to 4
        [calendar_month]   TINYINT NOT NULL,            -- 1 to 12
        [month_name]       NVARCHAR(20) NOT NULL,       -- e.g. March
        [year_month]       NVARCHAR(7) NOT NULL,        -- e.g. 2017-03 (handy for monthly trends)
        [day_of_month]     TINYINT NOT NULL,            -- 1 to 31
        [day_of_week]      TINYINT NOT NULL,            -- 1 = Monday ... 7 = Sunday
        [day_name]         NVARCHAR(20) NOT NULL,       -- e.g. Monday
        [is_weekend]       BIT NOT NULL,                -- 1 = Saturday or Sunday
        [dwh_load_ts]      DATETIME2 NOT NULL CONSTRAINT [df_dim_date_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]     INT NULL,                    -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_dim_date] PRIMARY KEY CLUSTERED ([date_key]),
        CONSTRAINT [uq_dim_date_full_date] UNIQUE ([full_date])
    );
END
GO

-- ============================================================================
-- 2. TABLE: gold.dim_geography
-- TRANSFORMATIONS: Built from silver.geolocation (already collapsed to 1 row per zip prefix).
--                  Customer or seller prefixes missing from it map to -1 (Unknown).
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'dim_geography')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[dim_geography]
    (
        [geography_key]   INT IDENTITY(1,1) NOT NULL,  -- surrogate key (-1 = Unknown row)
        [zip_code_prefix] NVARCHAR(10) NOT NULL,       -- business key: 5-character zip prefix
        [latitude]        DECIMAL(9,6) NULL,           -- average latitude for the prefix
        [longitude]       DECIMAL(9,6) NULL,           -- average longitude for the prefix
        [city]            NVARCHAR(100) NULL,          -- most frequent city for the prefix
        [state]           NVARCHAR(10) NULL,           -- upper-case state code
        [dwh_load_ts]     DATETIME2 NOT NULL CONSTRAINT [df_dim_geography_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]    INT NULL,                    -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_dim_geography] PRIMARY KEY CLUSTERED ([geography_key]),
        CONSTRAINT [uq_dim_geography_zip_code_prefix] UNIQUE ([zip_code_prefix])
    );
END
GO

-- ============================================================================
-- 3. TABLE: gold.dim_customer
-- TRANSFORMATIONS: SCD Type 2 on city/state. One row per VERSION of a customer_unique_id (NOT per
--                  customer_id). valid_from = order_purchase_ts of the first order seen in that
--                  city/state.
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'dim_customer')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[dim_customer]
    (
        [customer_key]       INT IDENTITY(1,1) NOT NULL,  -- surrogate key (-1 = Unknown row)
        [customer_unique_id] NVARCHAR(50) NOT NULL,       -- business key: the real person id
        [geography_key]      INT NOT NULL,                -- FK to dim_geography (zip prefix of this version)
        [customer_city]      NVARCHAR(100) NULL,          -- tracked by SCD2
        [customer_state]     NVARCHAR(10) NULL,           -- tracked by SCD2
        [valid_from]         DATETIME2 NOT NULL,          -- order_purchase_ts when this version was first seen
        [valid_to]           DATETIME2 NOT NULL CONSTRAINT [df_dim_customer_valid_to] DEFAULT '9999-12-31',  -- 9999-12-31 = open version
        [is_current]         BIT NOT NULL,                -- 1 = latest version of this customer
        [dwh_load_ts]        DATETIME2 NOT NULL CONSTRAINT [df_dim_customer_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]       INT NULL,                    -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_dim_customer] PRIMARY KEY CLUSTERED ([customer_key]),
        CONSTRAINT [fk_dim_customer_dim_geography] FOREIGN KEY ([geography_key]) REFERENCES [olist_dwh].[gold].[dim_geography] ([geography_key])
    );
END
GO

-- ============================================================================
-- 4. TABLE: gold.dim_product
-- TRANSFORMATIONS: Built from silver.products (misspelt columns already fixed, English category
--                  already joined, NULL category already 'Unknown').
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'dim_product')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[dim_product]
    (
        [product_key]                   INT IDENTITY(1,1) NOT NULL,  -- surrogate key (-1 = Unknown row)
        [product_id]                    NVARCHAR(50) NOT NULL,       -- business key
        [product_category_name]         NVARCHAR(200) NOT NULL,      -- Portuguese category, 'Unknown' when missing
        [product_category_name_english] NVARCHAR(200) NOT NULL,      -- English category, 'Unknown' when missing
        [product_name_length]           INT NULL,                    -- fixed spelling
        [product_description_length]    INT NULL,                    -- fixed spelling
        [product_photos_qty]            INT NULL,                    -- number of photos
        [product_weight_g]              INT NULL,                    -- weight in grams
        [product_length_cm]             INT NULL,                    -- length in cm
        [product_height_cm]             INT NULL,                    -- height in cm
        [product_width_cm]              INT NULL,                    -- width in cm
        [dwh_load_ts]                   DATETIME2 NOT NULL CONSTRAINT [df_dim_product_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]                  INT NULL,                    -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_dim_product] PRIMARY KEY CLUSTERED ([product_key]),
        CONSTRAINT [uq_dim_product_product_id] UNIQUE ([product_id])
    );
END
GO

-- ============================================================================
-- 5. TABLE: gold.dim_seller
-- TRANSFORMATIONS: Built from silver.sellers; the seller zip prefix is swapped for geography_key
--                  with a Lookup to dim_geography (no match = -1).
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'dim_seller')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[dim_seller]
    (
        [seller_key]    INT IDENTITY(1,1) NOT NULL,  -- surrogate key (-1 = Unknown row)
        [seller_id]     NVARCHAR(50) NOT NULL,       -- business key
        [geography_key] INT NOT NULL,                -- FK to dim_geography
        [seller_city]   NVARCHAR(100) NULL,          -- trimmed, proper case
        [seller_state]  NVARCHAR(10) NULL,           -- trimmed, upper case
        [dwh_load_ts]   DATETIME2 NOT NULL CONSTRAINT [df_dim_seller_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]  INT NULL,                    -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_dim_seller] PRIMARY KEY CLUSTERED ([seller_key]),
        CONSTRAINT [uq_dim_seller_seller_id] UNIQUE ([seller_id]),
        CONSTRAINT [fk_dim_seller_dim_geography] FOREIGN KEY ([geography_key]) REFERENCES [olist_dwh].[gold].[dim_geography] ([geography_key])
    );
END
GO

-- ============================================================================
-- 6. TABLE: gold.dim_order_status
-- TRANSFORMATIONS: Built from the distinct order_status values in silver.orders.
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'dim_order_status')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[dim_order_status]
    (
        [order_status_key] INT IDENTITY(1,1) NOT NULL,  -- surrogate key (-1 = Unknown row)
        [order_status]     NVARCHAR(20) NOT NULL,       -- business key: lower-case status
        [is_delivered]     BIT NOT NULL,                -- 1 when the status is delivered
        [dwh_load_ts]      DATETIME2 NOT NULL CONSTRAINT [df_dim_order_status_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]     INT NULL,                    -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_dim_order_status] PRIMARY KEY CLUSTERED ([order_status_key]),
        CONSTRAINT [uq_dim_order_status_order_status] UNIQUE ([order_status])
    );
END
GO

-- ============================================================================
-- 7. TABLE: gold.dim_payment_type
-- TRANSFORMATIONS: Built from the distinct payment_type values in silver.order_payments
--                  (not_defined was already standardised to 'Unknown' in Silver).
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'dim_payment_type')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[dim_payment_type]
    (
        [payment_type_key] INT IDENTITY(1,1) NOT NULL,  -- surrogate key (-1 = Unknown row)
        [payment_type]     NVARCHAR(30) NOT NULL,       -- business key: credit_card, boleto, voucher, debit_card, Unknown
        [dwh_load_ts]      DATETIME2 NOT NULL CONSTRAINT [df_dim_payment_type_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]     INT NULL,                    -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_dim_payment_type] PRIMARY KEY CLUSTERED ([payment_type_key]),
        CONSTRAINT [uq_dim_payment_type_payment_type] UNIQUE ([payment_type])
    );
END
GO
-- ============================================================================
-- 8. TABLE: gold.fact_sales
-- TRANSFORMATIONS: One row per order item from silver.order_items joined to silver.orders. Business
--                  keys are swapped for surrogate keys with SSIS Lookups (no match = -1). Delivery
--                  measures are derived ONLY for delivered orders.
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'fact_sales')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[fact_sales]
    (
        [order_id]                      NVARCHAR(50) NOT NULL,  -- degenerate dimension: the order
        [order_item_id]                 INT NOT NULL,           -- item number within the order
        [date_key]                      INT NOT NULL,           -- FK to dim_date: order purchase date
        [customer_key]                  INT NOT NULL,           -- FK to dim_customer: version valid at purchase
        [product_key]                   INT NOT NULL,           -- FK to dim_product
        [seller_key]                    INT NOT NULL,           -- FK to dim_seller (on the item row, not the order)
        [order_status_key]              INT NOT NULL,           -- FK to dim_order_status
        [price]                         DECIMAL(10,2) NULL,     -- item price
        [freight_value]                 DECIMAL(10,2) NULL,     -- freight for the item
        [total_item_value]              DECIMAL(10,2) NULL,     -- price + freight_value
        [order_purchase_ts]             DATETIME2 NULL,         -- kept for the delivery calculations
        [order_delivered_customer_date] DATETIME2 NULL,         -- NULL for undelivered orders
        [order_estimated_delivery_date] DATETIME2 NULL,         -- promised delivery date
        [days_to_deliver]               INT NULL,               -- derived; NULL when undelivered
        [delivery_delay_days]           INT NULL,               -- derived; positive = late; NULL when undelivered
        [is_late]                       BIT NULL,               -- derived; NULL when undelivered
        [dwh_load_ts]                   DATETIME2 NOT NULL CONSTRAINT [df_fact_sales_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]                  INT NULL,               -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_fact_sales] PRIMARY KEY CLUSTERED ([order_id], [order_item_id]),
        CONSTRAINT [fk_fact_sales_dim_date] FOREIGN KEY ([date_key]) REFERENCES [olist_dwh].[gold].[dim_date] ([date_key]),
        CONSTRAINT [fk_fact_sales_dim_customer] FOREIGN KEY ([customer_key]) REFERENCES [olist_dwh].[gold].[dim_customer] ([customer_key]),
        CONSTRAINT [fk_fact_sales_dim_product] FOREIGN KEY ([product_key]) REFERENCES [olist_dwh].[gold].[dim_product] ([product_key]),
        CONSTRAINT [fk_fact_sales_dim_seller] FOREIGN KEY ([seller_key]) REFERENCES [olist_dwh].[gold].[dim_seller] ([seller_key]),
        CONSTRAINT [fk_fact_sales_dim_order_status] FOREIGN KEY ([order_status_key]) REFERENCES [olist_dwh].[gold].[dim_order_status] ([order_status_key])
    );
END
GO

-- ============================================================================
-- 9. TABLE: gold.fact_payments
-- TRANSFORMATIONS: One row per payment line from silver.order_payments joined to silver.orders (for
--                  the customer and the purchase date). Business keys are swapped for surrogate
--                  keys with SSIS Lookups (no match = -1).
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'fact_payments')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[fact_payments]
    (
        [order_id]             NVARCHAR(50) NOT NULL,  -- degenerate dimension: the order
        [payment_sequential]   INT NOT NULL,           -- payment line number within the order
        [date_key]             INT NOT NULL,           -- FK to dim_date: order purchase date
        [customer_key]         INT NOT NULL,           -- FK to dim_customer: version valid at purchase
        [payment_type_key]     INT NOT NULL,           -- FK to dim_payment_type
        [payment_installments] INT NULL,               -- number of installments
        [payment_value]        DECIMAL(10,2) NULL,     -- payment amount
        [dwh_load_ts]          DATETIME2 NOT NULL CONSTRAINT [df_fact_payments_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]         INT NULL,               -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_fact_payments] PRIMARY KEY CLUSTERED ([order_id], [payment_sequential]),
        CONSTRAINT [fk_fact_payments_dim_date] FOREIGN KEY ([date_key]) REFERENCES [olist_dwh].[gold].[dim_date] ([date_key]),
        CONSTRAINT [fk_fact_payments_dim_customer] FOREIGN KEY ([customer_key]) REFERENCES [olist_dwh].[gold].[dim_customer] ([customer_key]),
        CONSTRAINT [fk_fact_payments_dim_payment_type] FOREIGN KEY ([payment_type_key]) REFERENCES [olist_dwh].[gold].[dim_payment_type] ([payment_type_key])
    );
END
GO

-- ============================================================================
-- 10. TABLE: gold.fact_reviews
-- TRANSFORMATIONS: One row per review from silver.order_reviews (already de-duplicated on
--                  review_id) joined to silver.orders (for the customer). Business keys are swapped
--                  for surrogate keys with SSIS Lookups (no match = -1).
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'fact_reviews')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[fact_reviews]
    (
        [review_id]               NVARCHAR(50) NOT NULL,  -- business key of the review
        [order_id]                NVARCHAR(50) NOT NULL,  -- degenerate dimension: the order reviewed
        [date_key]                INT NOT NULL,           -- FK to dim_date: review creation date
        [customer_key]            INT NOT NULL,           -- FK to dim_customer: version valid at purchase
        [review_score]            TINYINT NULL,           -- 1 to 5
        [review_creation_date]    DATETIME2 NULL,         -- survey sent
        [review_answer_timestamp] DATETIME2 NULL,         -- survey answered
        [dwh_load_ts]             DATETIME2 NOT NULL CONSTRAINT [df_fact_reviews_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]            INT NULL,               -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_fact_reviews] PRIMARY KEY CLUSTERED ([review_id]),
        CONSTRAINT [fk_fact_reviews_dim_date] FOREIGN KEY ([date_key]) REFERENCES [olist_dwh].[gold].[dim_date] ([date_key]),
        CONSTRAINT [fk_fact_reviews_dim_customer] FOREIGN KEY ([customer_key]) REFERENCES [olist_dwh].[gold].[dim_customer] ([customer_key])
    );
END
GO

-- ============================================================================
-- PROJECT: PHASE 3
-- PURPOSE: Adds a default "Unknown" placeholder record (ID: -1) to each list.
--          If an order is missing details like a customer or product, the
--          system points to this placeholder so reports never break.
--          Safe to run multiple times without creating duplicates.
-- ============================================================================

USE [olist_dwh];
GO

-- ============================================================================
-- 1. ADD "UNKNOWN" PLACEHOLDER TO THE CALENDAR LIST (dim_date)
-- ============================================================================
SET IDENTITY_INSERT [gold].[dim_date] ON;
IF NOT EXISTS (SELECT 1 FROM [gold].[dim_date] WHERE [date_key] = -1)
BEGIN
    INSERT INTO [gold].[dim_date] (
        [date_key], [full_date], [calendar_year], [calendar_quarter], 
        [calendar_month], [month_name], [year_month], [day_of_month], 
        [day_of_week], [day_name], [is_weekend], [dwh_batch_id]
    )
    VALUES (
        -1, '1900-01-01', 1900, 1, 
        1, N'Unknown', N'1900-01', 1, 
        1, N'Unknown', 0, -1
    );
END
SET IDENTITY_INSERT [gold].[dim_date] OFF;
GO

-- ============================================================================
-- 2. ADD "UNKNOWN" PLACEHOLDER TO THE LOCATIONS LIST (dim_geography)
-- NOTE: Must run before Customers and Sellers because they link to locations.
-- ============================================================================
SET IDENTITY_INSERT [gold].[dim_geography] ON;
IF NOT EXISTS (SELECT 1 FROM [gold].[dim_geography] WHERE [geography_key] = -1)
BEGIN
    INSERT INTO [gold].[dim_geography] (
        [geography_key], [zip_code_prefix], [latitude], [longitude], 
        [city], [state], [dwh_batch_id]
    )
    VALUES (
        -1, N'Unknown', NULL, NULL, 
        N'Unknown', N'Unknown', -1
    );
END
SET IDENTITY_INSERT [gold].[dim_geography] OFF;
GO

-- ============================================================================
-- 3. ADD "UNKNOWN" PLACEHOLDER TO THE CUSTOMERS LIST (dim_customer)
-- ============================================================================
SET IDENTITY_INSERT [gold].[dim_customer] ON;
IF NOT EXISTS (SELECT 1 FROM [gold].[dim_customer] WHERE [customer_key] = -1)
BEGIN
    INSERT INTO [gold].[dim_customer] (
        [customer_key], [customer_unique_id], [geography_key], [customer_city], 
        [customer_state], [valid_from], [valid_to], [is_current], [dwh_batch_id]
    )
    VALUES (
        -1, N'Unknown', -1, N'Unknown', 
        N'Unknown', '1900-01-01', '9999-12-31', 1, -1
    );
END
SET IDENTITY_INSERT [gold].[dim_customer] OFF;
GO

-- ============================================================================
-- 4. ADD "UNKNOWN" PLACEHOLDER TO THE PRODUCTS LIST (dim_product)
-- ============================================================================
SET IDENTITY_INSERT [gold].[dim_product] ON;
IF NOT EXISTS (SELECT 1 FROM [gold].[dim_product] WHERE [product_key] = -1)
BEGIN
    INSERT INTO [gold].[dim_product] (
        [product_key], [product_id], [product_category_name], 
        [product_category_name_english], [dwh_batch_id]
    )
    VALUES (
        -1, N'Unknown', N'Unknown', 
        N'Unknown', -1
    );
END
SET IDENTITY_INSERT [gold].[dim_product] OFF;
GO

-- ============================================================================
-- 5. ADD "UNKNOWN" PLACEHOLDER TO THE SELLERS LIST (dim_seller)
-- ============================================================================
SET IDENTITY_INSERT [gold].[dim_seller] ON;
IF NOT EXISTS (SELECT 1 FROM [gold].[dim_seller] WHERE [seller_key] = -1)
BEGIN
    INSERT INTO [gold].[dim_seller] (
        [seller_key], [seller_id], [geography_key], 
        [seller_city], [seller_state], [dwh_batch_id]
    )
    VALUES (
        -1, N'Unknown', -1, 
        N'Unknown', N'Unknown', -1
    );
END
SET IDENTITY_INSERT [gold].[dim_seller] OFF;
GO

-- ============================================================================
-- 6. ADD "UNKNOWN" PLACEHOLDER TO THE ORDER STATUS LIST (dim_order_status)
-- ============================================================================
SET IDENTITY_INSERT [gold].[dim_order_status] ON;
IF NOT EXISTS (SELECT 1 FROM [gold].[dim_order_status] WHERE [order_status_key] = -1)
BEGIN
    INSERT INTO [gold].[dim_order_status] (
        [order_status_key], [order_status], [is_delivered], [dwh_batch_id]
    )
    VALUES (
        -1, N'Unknown', 0, -1
    );
END
SET IDENTITY_INSERT [gold].[dim_order_status] OFF;
GO

-- ============================================================================
-- 7. ADD "UNKNOWN" PLACEHOLDER TO THE PAYMENT METHODS LIST (dim_payment_type)
-- ============================================================================
SET IDENTITY_INSERT [gold].[dim_payment_type] ON;
IF NOT EXISTS (SELECT 1 FROM [gold].[dim_payment_type] WHERE [payment_type_key] = -1)
BEGIN
    INSERT INTO [gold].[dim_payment_type] (
        [payment_type_key], [payment_type], [dwh_batch_id]
    )
    VALUES (
        -1, N'Unknown', -1
    );
